import pandas as pd


def clean(df):
    df = df.copy()
    # body_mass_g is stored as text (e.g. '3450'); convert to numeric for summing
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    # remove exact duplicate rows (profile reports 2 exact duplicates)
    df = df.drop_duplicates()
    return df


def answer(df):
    result = {}
    grouped = df.groupby('species')['body_mass_g'].sum()
    for species, total in grouped.items():
        if pd.isna(species):
            continue
        result[species] = total
    return result
